import android.content.Context;
import android.content.SharedPreferences;
import com.androidhit.lumadrift.data.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;

/** Real production data classes, deterministic preference/clock adapters only. No device/provider. */
public final class EconomyStateStress {
 static long checks,actions,coldBoots,failedCommits; static int sessionIndex,step; static long seed;
 static final Map<String,long[]> families=new TreeMap<>();static final List<String> trace=new ArrayList<>();
 static void ck(boolean v,String message){checks++;if(!v)throw new AssertionError("session="+sessionIndex+" step="+step+" "+message+" trace="+trace);}
 static void count(String name,boolean accepted){actions++;long[] a=families.computeIfAbsent(name,k->new long[3]);a[0]++;a[accepted?1:2]++;trace.add(name+":"+accepted);}
 static final class Prefs implements SharedPreferences {
  final Map<String,Object> memory=new HashMap<>(),disk=new HashMap<>();boolean fail,memoryFirst;int commits;
  public Map<String,?> getAll(){return new HashMap<>(memory);}public boolean contains(String k){return memory.containsKey(k);}
  public int getInt(String k,int d){return (Integer)memory.getOrDefault(k,d);}public String getString(String k,String d){return (String)memory.getOrDefault(k,d);}public boolean getBoolean(String k,boolean d){return (Boolean)memory.getOrDefault(k,d);}
  public Editor edit(){Map<String,Object> write=new HashMap<>();return new Editor(){public Editor putInt(String k,int v){write.put(k,v);return this;}public Editor putString(String k,String v){write.put(k,v);return this;}public Editor putBoolean(String k,boolean v){write.put(k,v);return this;}public boolean commit(){commits++;if(fail){fail=false;if(memoryFirst)memory.putAll(write);failedCommits++;return false;}memory.putAll(write);disk.putAll(write);return true;}};}
  Prefs reboot(){Prefs p=new Prefs();p.memory.putAll(disk);p.disk.putAll(disk);return p;}
 }
 static final class Ctx extends Context {final Map<String,Prefs> files=new HashMap<>();public SharedPreferences getSharedPreferences(String name,int mode){return files.computeIfAbsent(name,k->new Prefs());}Prefs save(){return files.get("luma_drift_save_v1");}Prefs energy(){return (Prefs)getSharedPreferences("stress_energy_separate",0);}Ctx reboot(){Ctx c=new Ctx();files.forEach((k,p)->c.files.put(k,p.reboot()));return c;}}
 static final class Time implements GameStore.Clock{long now=1793404800000L;public long now(){return now;}}
 static GameStore store(Ctx c,Time time){return new GameStore(c,null,time);}
 static String run(int n){return String.format(Locale.ROOT,"00000000-0000-0000-0000-%012d",n);}
 static String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 static Map<CosmeticCatalog.Slot,String> look(GameStore g){Map<CosmeticCatalog.Slot,String> m=new EnumMap<>(CosmeticCatalog.Slot.class);for(var s:CosmeticCatalog.Slot.values())m.put(s,g.equippedCosmetic(s));return m;}
 static String fingerprint(GameStore g,SessionEnergyStore e,Time t){StringBuilder s=new StringBuilder().append(g.coins()).append('/').append(g.unlockedLevel()).append('/').append(g.homeRoom()).append('/').append(g.equippedCharacter()).append('/').append(g.usesOriginalCompanionCostume()).append('/').append(look(g)).append('/').append(e.maximum()).append('/').append(e.snapshot(t.now).count);for(String r:HomeCatalog.ROOMS)s.append('/').append(g.homeLayout(r).encode()).append('/').append(g.homeWallpaper(r)).append('/').append(g.homeFloor(r));for(var slot:AvatarGearCatalog.Slot.values())s.append('/').append(g.avatarLoadout().item(slot).id);return s.toString();}
 static void invariants(GameStore g,SessionEnergyStore e,Time t){
  ck(g.coins()>=0&&g.coins()<=2_000_000_000,"local Coins bounds");var en=e.snapshot(t.now);ck(en.count>=0&&en.count<=e.maximum(),"energy bounds");ck(en.count==e.maximum()?en.nextInMs==0:en.nextInMs>=1&&en.nextInMs<=600000,"energy clock bound");
  for(var s:CosmeticCatalog.Slot.values()){var i=CosmeticCatalog.find(g.equippedCosmetic(s));ck(i!=null&&i.slot==s&&g.ownsCosmetic(i.id),"equipped wardrobe owned in correct slot");}
  ck(g.ownsCharacter(g.equippedCharacter()),"displayed character owned");for(var slot:AvatarGearCatalog.Slot.values())ck(g.ownsAvatarGear(g.avatarLoadout().item(slot).id),"equipped gear owned");
  for(String room:HomeCatalog.ROOMS){HomeLayout l=g.homeLayout(room);ck(HomeLayout.decode(l.encode()).encode().equals(l.encode()),"home entire-record roundtrip");ck(!l.isBlocked(l.companionX,l.companionY),"companion never in solid furniture");for(var p:l.placements())ck(g.ownsHomeItem(p.itemId),"placed furniture owned");ck(g.ownsHomeItem(g.homeWallpaper(room))&&g.ownsHomeItem(g.homeFloor(room)),"room finishes owned");}
 }
 static void randomized(int sessions,int steps,Path out)throws Exception{
  StringBuilder csv=new StringBuilder("session,seed,actions,finalCoins,unlocked,energy,traceSha256,stateSha256\n");
  for(sessionIndex=0;sessionIndex<sessions;sessionIndex++){
   trace.clear();long localSeed=seed+sessionIndex*1000003L;Random r=new Random(localSeed);Time t=new Time();Ctx c=new Ctx();GameStore g=store(c,t);SessionEnergyStore e=new SessionEnergyStore(c.energy());
   // Only the cosmetic PRNG seed is a direct fixture. No balance/ownership/progression injection.
   c.save().edit().putString("cosmetic_seed_v17","stress-"+localSeed).commit();
   for(int n=0;n<sessionIndex%3;n++)ck(g.grantMilestone("declared-test-funding-"+n,500)==500,"bounded public funding fixture");
   Set<String> ownedHome=new HashSet<>();for(var i:HomeCatalog.ITEMS)if(i.price==0)ownedHome.add(i.id);for(var i:HomeCatalog.WALLPAPERS)if(i.price==0)ownedHome.add(i.id);for(var i:HomeCatalog.FLOORS)if(i.price==0)ownedHome.add(i.id);
   Map<String,GameStore.LootResult> capsuleReceipts=new HashMap<>();String pending="",last="";int energySeq=0;
   for(step=0;step<steps;step++){
    int op=r.nextInt(24),before=g.coins();Map<String,Object> diskBefore=new HashMap<>(c.save().disk);String room=g.homeRoom();Map<String,String> otherRooms=new HashMap<>();for(String id:HomeCatalog.ROOMS)if(!id.equals(room))otherRooms.put(id,g.homeLayout(id).encode());
    switch(op){
     case 0->{String id=r.nextInt(8)==0?"unknown":HomeCatalog.ITEMS.get(r.nextInt(HomeCatalog.ITEMS.size())).id;int price=HomeCatalog.price(id);boolean expected=price>=0&&!ownedHome.contains(id)&&before>=price;boolean got=g.purchaseHomeItem(id);ck(got==expected,"home purchase decision");ck(g.coins()==before-(got?price:0),"home exact one debit");if(got)ownedHome.add(id);int b=g.coins();ck(!g.purchaseHomeItem(id)&&g.coins()==b,"duplicate/refused home purchase cannot debit");count("home-purchase-and-retry",got);}
     case 1->{String id=r.nextInt(8)==0?"unknown":HomeCatalog.ITEMS.get(r.nextInt(HomeCatalog.ITEMS.size())).id;int x=r.nextInt(14)-2,y=r.nextInt(14)-2,rotation=r.nextInt(4)-1;HomeLayout old=g.homeLayout(),next=old.tryPlace(id,x,y,rotation);boolean expected=ownedHome.contains(id)&&HomeCatalog.item(id)!=null&&next!=null;boolean got=g.placeHomeItem(id,x,y,rotation);ck(got==expected,"real owned geometry decides placement");ck(g.homeLayout().encode().equals(got?next.encode():old.encode()),"placement exact or unchanged");ck(g.coins()==before,"placement free");count("home-place-valid-invalid",got);}
     case 2->{var l=g.homeLayout();String id=!l.placements().isEmpty()&&r.nextBoolean()?l.placements().get(r.nextInt(l.placements().size())).id:"unknown";boolean expected=l.placement(id)!=null;boolean got=g.removeHomeItem(id);ck(got==expected,"remove decision");ck(g.coins()==before,"remove no refund or charge");count("home-remove",got);}
     case 3->{int x=r.nextInt(14)-2,y=r.nextInt(14)-2;HomeLayout old=g.homeLayout(),next=old.tryMove(x,y);boolean got=g.moveHomeCompanion(x,y);ck(got==(next!=null),"home walk reachability");ck(g.homeLayout().encode().equals(got?next.encode():old.encode()),"home walk destination preserved");ck(g.coins()==before,"home walk cannot debit");count("home-walk",got);}
     case 4->{String id=r.nextInt(6)==0?"unknown":HomeCatalog.ROOMS.get(r.nextInt(4));boolean got=g.setHomeRoom(id);ck(got==HomeCatalog.validRoom(id),"room selector validity");ck(g.homeRoom().equals(got?id:room),"room context exact");ck(g.coins()==before,"room selection free");count("home-room",got);}
     case 5->{boolean wall=r.nextBoolean();String id=wall?HomeCatalog.WALLPAPERS.get(r.nextInt(HomeCatalog.WALLPAPERS.size())).id:HomeCatalog.FLOORS.get(r.nextInt(HomeCatalog.FLOORS.size())).id;if(r.nextBoolean()){int price=HomeCatalog.price(id);boolean expectBuy=!ownedHome.contains(id)&&before>=price;boolean bought=g.purchaseHomeItem(id);ck(bought==expectBuy,"finish purchase ownership");ck(g.coins()==before-(bought?price:0),"finish purchase exact debit");if(bought)ownedHome.add(id);before=g.coins();}boolean expected=ownedHome.contains(id);boolean got=wall?g.setHomeWallpaper(id):g.setHomeFloor(id);ck(got==expected,"finish requires ownership");ck(g.coins()==before,"finish application not purchase");count("home-finish",got);}
     case 6->{var i=CosmeticCatalog.ITEMS.get(r.nextInt(CosmeticCatalog.ITEMS.size()));boolean owned=g.ownsCosmetic(i.id);boolean expected=i.source==CosmeticCatalog.Source.EARNED_COINS&&!owned&&before>=i.priceCoins;boolean got=g.purchaseCosmetic(i.id);ck(got==expected,"wardrobe purchase decision");ck(g.coins()==before-(got?i.priceCoins:0),"wardrobe exact debit");int b=g.coins();ck(!g.purchaseCosmetic(i.id)&&g.coins()==b,"wardrobe retry no second debit");count("wardrobe-purchase-and-retry",got);}
     case 7->{Map<CosmeticCatalog.Slot,String> draft=look(g);boolean original=r.nextBoolean();if(r.nextBoolean()){var i=CosmeticCatalog.ITEMS.get(r.nextInt(CosmeticCatalog.ITEMS.size()));draft.put(i.slot,i.id);}if(r.nextInt(8)==0)draft.remove(CosmeticCatalog.Slot.HAT);boolean expected=draft.size()==4;for(var s:CosmeticCatalog.Slot.values()){var i=CosmeticCatalog.find(draft.get(s));expected&=i!=null&&i.slot==s&&g.ownsCosmetic(i.id);}var old=look(g);boolean wasOriginal=g.usesOriginalCompanionCostume();boolean got=g.applyCosmeticLook123(draft,original);ck(got==expected,"complete draft all-or-nothing ownership");ck(look(g).equals(got?draft:old)&&g.usesOriginalCompanionCostume()==(got?original:wasOriginal),"wardrobe application exact");ck(g.coins()==before,"confirmed look no charge");if(!got)ck(c.save().disk.equals(diskBefore),"refused wardrobe no write");count("wardrobe-confirm-or-refuse",got);}
     case 8->{String id="capsule-"+r.nextInt(5);var prior=capsuleReceipts.get(id);var selected=CosmeticCatalog.draw("stress-"+localSeed,id);boolean duplicate=g.ownsCosmetic(selected.id);int compensation=duplicate?selected.duplicateCoins():0;boolean expected=prior!=null||before>=150;var got=g.drawCosmeticLoot(id);ck((got!=null)==expected,"capsule sufficient earned Coins or existing receipt");if(got!=null){ck(got.itemId.equals(selected.id),"fixed seed and request outcome");ck(got.replayed==(prior!=null)&&got.chargedCoins==(prior==null?150:0),"capsule retry cannot reroll or debit");ck(g.coins()==before+(prior==null?-150+compensation:0),"capsule exact charge and disclosed duplicate refund");ck(g.ownsCosmetic(got.itemId),"capsule grants owned cosmetic");capsuleReceipts.put(id,got);int b=g.coins();var again=g.drawCosmeticLoot(id);ck(again.replayed&&again.chargedCoins==0&&again.itemId.equals(got.itemId)&&again.compensationCoins==got.compensationCoins&&g.coins()==b,"capsule replay stable grant compensation and balance");}count("earned-capsule-and-retry",got!=null);}

     case 9->{var i=AvatarGearCatalog.ITEMS.get(r.nextInt(AvatarGearCatalog.ITEMS.size()));boolean expected=i.source==AvatarGearCatalog.Source.EARNED_COINS&&!g.ownsAvatarGear(i.id)&&before>=i.priceCoins;boolean got=g.purchaseAvatarGear(i.id);ck(got==expected,"gear purchase ownership");ck(g.coins()==before-(got?i.priceCoins:0),"gear exact debit");int b=g.coins();ck(!g.purchaseAvatarGear(i.id)&&g.coins()==b,"gear repeated buy no debit");count("gear-purchase-and-retry",got);}
     case 10->{var i=AvatarGearCatalog.ITEMS.get(r.nextInt(AvatarGearCatalog.ITEMS.size()));boolean expected=g.ownsAvatarGear(i.id);boolean got=g.equipAvatarGear(i.id);ck(got==expected&&g.coins()==before,"gear equip owned and free");count("gear-equip",got);}
     case 11->{int level=Math.min(g.unlockedLevel(),1+r.nextInt(12));int stars=1+r.nextInt(3),old=g.stars(level);int expected=stars>old?EconomyCurve121.campaignReward(level,stars)-(old==0?0:EconomyCurve121.campaignReward(level,old)):0;int got=g.completeLevel(level,stars,true);ck(got==expected&&g.coins()==before+expected,"star-difference reward");int b=g.coins();ck(g.completeLevel(level,stars,true)==0&&g.coins()==b,"duplicate victory no farming");count("journey-reward-and-retry",got>0);}
     case 12->{String id="milestone-"+r.nextInt(4);boolean already=c.save().getBoolean("milestone_"+id,false);int amount=1+r.nextInt(500);int got=g.grantMilestone(id,amount);ck(got==(already?0:amount)&&g.coins()==before+got,"milestone one credit");int b=g.coins();ck(g.grantMilestone(id,amount)==0&&g.coins()==b,"milestone duplicate stable");count("milestone-and-retry",got>0);}
     case 13->{boolean claimed=g.dailyLoginClaimed();int reward=g.dailyLoginCoins(g.dailyLoginDay());int got=g.claimDailyLogin();ck(got==(claimed?0:reward)&&g.coins()==before+got,"daily login entitlement");int b=g.coins();ck(g.claimDailyLogin()==0&&g.coins()==b,"login retry no grant");count("login-and-retry",got>0);}
     case 14->{String id="undo-"+r.nextInt(6);int lvl=1+r.nextInt(1000),paid=1+r.nextInt(8),price=EconomyCurve121.undoPrice(lvl,paid);var p=g.pendingUndo121();String receipt=c.save().getString("undo121_receipt_"+id,"");boolean expected=receipt.equals("reserved:"+price)?p!=null&&p.requestId.equals(id):receipt.isEmpty()&&p==null&&before>=price;boolean got=g.reserveUndo121(id,lvl,paid);ck(got==expected,"undo quote and one reservation");ck(g.coins()==before-(got&&receipt.isEmpty()?price:0),"undo no duplicate debit");count("undo-reserve",got);}
     case 15->{var p=g.pendingUndo121();String id=p==null?"not-reserved":p.requestId;boolean cancel=r.nextBoolean();int refund=p==null?0:p.coins;boolean got=cancel?g.cancelUndo121(id):g.completeUndo121(id);ck(got==(p!=null),"undo finalization identity");ck(g.coins()==before+(got&&cancel?refund:0),"undo exact one refund");int b=g.coins();boolean dup=cancel?g.cancelUndo121(id):g.completeUndo121(id);ck(dup==got&&g.coins()==b,"undo finalize duplicate stable");count("undo-confirm-or-refund-and-retry",got);}
     case 16->{String id=run(++energySeq);int old=e.snapshot(t.now).count;boolean expected=pending.isEmpty()&&old>0;boolean got=e.reserve(id,t.now);ck(got==expected&&e.snapshot(t.now).count==old-(got?1:0),"energy one debit");if(got){pending=id;int b=e.snapshot(t.now).count;ck(e.reserve(id,t.now)&&e.snapshot(t.now).count==b,"same run resume free");}count("energy-reserve-and-retry",got);}
     case 17->{int old=e.snapshot(t.now).count;boolean durable=r.nextBoolean();String id=durable?pending:"";e.recover(id,"",t.now);ck(e.snapshot(t.now).count==Math.min(e.maximum(),old+(!pending.isEmpty()&&!durable?1:0)),"pending energy reconcile once");if(durable&&!pending.isEmpty())last=pending;pending="";int b=e.snapshot(t.now).count;e.recover(id,"",t.now);ck(e.snapshot(t.now).count==b,"duplicate recovery free");if(!last.isEmpty()){ck(e.reserve(last,t.now)&&e.snapshot(t.now).count==b,"durable last board resume free");}count("energy-recover",true);}
     case 18->{var old=e.snapshot(t.now);long delta=r.nextInt(1800001);t.now+=delta;int ticks=old.nextInMs==0?0:delta>=old.nextInMs?1+(int)((delta-old.nextInMs)/SessionEnergyStore.REFILL_MS):0;ck(e.snapshot(t.now).count==Math.min(e.maximum(),old.count+ticks),"elapsed ten-minute refill");count("clock-advance-and-refill",true);}
     case 19->{String receipt=hash("fixture-receipt-"+r.nextInt(6));int old=e.snapshot(t.now).count;boolean already=e.hasReceipt(receipt);boolean got=e.creditReceipt(receipt,10,t.now);ck(got!=already&&e.snapshot(t.now).count==(already?old:Math.min(e.maximum(),old+10)),"receipt one bounded credit");int b=e.snapshot(t.now).count;ck(!e.creditReceipt(receipt,10,t.now)&&e.snapshot(t.now).count==b,"receipt replay no extra credit");count("energy-fixture-receipt-and-retry",got);}
     case 20->{String a=fingerprint(g,e,t);c=c.reboot();g=store(c,t);e=new SessionEnergyStore(c.energy());coldBoots++;ck(fingerprint(g,e,t).equals(a),"cold all-state persistence");count("cold-reconstruction",true);}
     case 21->{String id="ad-fixture-"+r.nextInt(4);boolean had=g.isGoldGranted(id);int got=g.grantGold(id,35);ck(got==(had?0:35)&&g.coins()==before+got,"ad earned-Coins receipt stable");int b=g.coins();ck(g.grantGold(id,35)==0&&g.coins()==b,"duplicate callback no credit");count("ad-coins-earned-callback-fixture",got>0);}
     case 22->{int old=e.maximum(),n=e.snapshot(t.now).count;e.setCapacity(10+r.nextInt(7),t.now);ck(e.maximum()>=old&&e.snapshot(t.now).count==n,"capacity never grants energy");count("energy-capacity",true);}
     case 23->{String id=List.of("nova","miko","hoot","orbit","unknown").get(r.nextInt(5));boolean own=g.ownsCharacter(id);boolean got=g.equipCharacter(id);ck(got==own&&g.coins()==before,"display companion requires ownership without spend");count("display-character",got);}
    }
    if(op!=4)ck(g.homeRoom().equals(room),"other action cannot switch home context");
    if(op==1||op==2||op==3||op==5)for(var pair:otherRooms.entrySet())ck(g.homeLayout(pair.getKey()).encode().equals(pair.getValue()),"edit never leaks into another room");
    if(step%8==0)invariants(g,e,t);
   }
   invariants(g,e,t);String f=fingerprint(g,e,t);csv.append(sessionIndex).append(',').append(localSeed).append(',').append(steps).append(',').append(g.coins()).append(',').append(g.unlockedLevel()).append(',').append(e.snapshot(t.now).count).append(',').append(hash(String.join("|",trace))).append(',').append(hash(f)).append('\n');
  }
  Files.writeString(out.resolve("sessions.csv"),csv);
 }
 static void faults(int cases){
  for(int n=0;n<cases;n++){
   sessionIndex=10000+n;step=-1;trace.clear();boolean memoryFirst=(n&1)==1;Time t=new Time();Ctx c=new Ctx();GameStore g=store(c,t);g.grantMilestone("fault-fixture-funding",500);var before=new HashMap<>(c.save().disk);int coins=g.coins();c.save().fail=true;c.save().memoryFirst=memoryFirst;boolean failed=false;try{g.purchaseHomeItem("sofa");}catch(GameStore.LocalSaveException expected){failed=true;}ck(failed&&c.save().disk.equals(before),"failed home purchase durable all-or-nothing");Ctx cold=c.reboot();GameStore old=store(cold,t);coldBoots++;ck(old.coins()==coins&&!old.ownsHomeItem("sofa"),"cold sees old complete purchase");g.retryPendingLocalSave();ck(g.coins()==coins-240&&g.ownsHomeItem("sofa"),"same-process retry writes accepted purchase once");ck(!g.purchaseHomeItem("sofa")&&g.coins()==coins-240,"retry call no second debit");count("fault-purchase-atomic-retry",true);
   var draft=look(g);boolean prior=g.usesOriginalCompanionCostume();before=new HashMap<>(c.save().disk);c.save().fail=true;c.save().memoryFirst=memoryFirst;failed=false;try{g.applyCosmeticLook123(draft,!prior);}catch(GameStore.LocalSaveException expected){failed=true;}ck(failed&&c.save().disk.equals(before),"failed look one atomic durable state");draft.put(CosmeticCatalog.Slot.HAT,"unknown");g.retryPendingLocalSave();ck(!g.usesOriginalCompanionCostume()==prior&&g.equippedCosmetic(CosmeticCatalog.Slot.HAT).equals("hat_dew"),"immutable accepted draft survives caller mutation");count("fault-look-atomic-retry",true);
   SessionEnergyStore e=new SessionEnergyStore(c.energy());e.snapshot(t.now);var energyDisk=new HashMap<>(c.energy().disk);c.energy().fail=true;c.energy().memoryFirst=memoryFirst;failed=false;try{e.reserve(run(n+1),t.now);}catch(GameStore.LocalSaveException expected){failed=true;}ck(failed&&c.energy().disk.equals(energyDisk),"failed energy debit unchanged durable");ck(e.reserve(run(n+1),t.now)&&e.snapshot(t.now).count==9,"failed energy retry once");e.recover("","",t.now);ck(e.snapshot(t.now).count==10,"missing durable board refunds once");e.recover("","",t.now);ck(e.snapshot(t.now).count==10,"repeat refund no extra");count("fault-energy-reserve-recover",true);
  }
 }
 public static void main(String[] args)throws Exception{
  Path out=Path.of(args[0]);Files.createDirectories(out);seed=Long.parseLong(args[1]);int sessions=Integer.parseInt(args[2]),steps=Integer.parseInt(args[3]);long started=System.nanoTime();
  try{randomized(sessions,steps,out);faults(2000);}catch(Throwable fail){Files.writeString(out.resolve("failure.txt"),fail.toString()+"\n");throw fail;}
  StringBuilder family=new StringBuilder("actionFamily,invocations,accepted,refusedOrAlreadyRecorded\n");for(var p:families.entrySet()){family.append(p.getKey());for(long x:p.getValue())family.append(',').append(x);family.append('\n');}Files.writeString(out.resolve("action-families.csv"),family);
  String json="{\n  \"status\":\"PASS\",\n  \"seed\":"+seed+",\n  \"randomizedSessions\":"+sessions+",\n  \"randomizedActionsPerSession\":"+steps+",\n  \"randomizedActions\":"+(sessions*(long)steps)+",\n  \"additionalFaultScenarios\":2000,\n  \"countedActionGroups\":"+actions+",\n  \"assertions\":"+checks+",\n  \"coldReconstructions\":"+coldBoots+",\n  \"failedCommitsInjected\":"+failedCommits+",\n  \"elapsedSeconds\":"+((System.nanoTime()-started)/1e9)+",\n  \"scope\":\"Actual GameStore, HomeLayout, catalogues, EconomyCurve121 and SessionEnergyStore APIs. Host preference/clock doubles; deterministic cosmetic seed fixture, bounded public milestone funding fixture, earned-ad callback and verified-energy receipt fixtures. No Android/physical persistence, live ad, purchase, backend, UI draft/context or human validation. No UI cancel is tested.\"\n}\n";Files.writeString(out.resolve("summary.json"),json);System.out.print(json);
 }
}
